        ipnsName: testIpnsName,
        record: testRecord,
        metadataCid: testMetadataCid,
      });

      expect(mockMetricsService.ipnsPublishDuration.observe).toHaveBeenCalledWith(
        { outcome: 'error' },
        expect.any(Number)
      );
    });

